theorem List.findIdxs_cons.{u_1} {α : Type u_1} {x : α} {xs : List α} {p : α → Bool} {s : ℕ} :
  List.findIdxs p (x :: xs) s =
    if p x = true then s :: List.findIdxs p xs (s + 1) else List.findIdxs p xs (s + 1)

