theorem List.foldlIdx_cons.{u_1, u_2} {α : Type u_1} {x : α} {xs : List α} {α✝ : Sort u_2}
  {f : ℕ → α✝ → α → α✝} {i : α✝} {s : ℕ} :
  List.foldlIdx f i (x :: xs) s = List.foldlIdx f (f s i x) xs (s + 1)

theorem List.findIdxNth_eq_findIdxNth_iff_of_right_lt_countP.{u_1} {α : Type u_1} {m : ℕ} {p : α → Bool}
  {n : ℕ} {xs : List α} (hm : m < List.countP p xs) :
