theorem List.foldlIdx_eq_foldl_zipIdx.{u_1, u_2} {α : Type u_1} {xs : List α} {α✝ : Type u_2}
  {f : ℕ → α✝ → α → α✝} {i : α✝} {s : ℕ} :
  List.foldlIdx f i xs s = List.foldl (fun b ab => f ab.2 b ab.1) i (xs.zipIdx s)

theorem List.idxsOf_cons.{u_1} {α : Type u_1} {x : α} {xs : List α} {y : α} {s : ℕ} [BEq α] :
  List.idxsOf y (x :: xs) s =
    if (x == y) = true then s :: List.idxsOf y xs (s + 1) else List.idxsOf y xs (s + 1)

theorem List.findIdxNth_eq_findIdxNth_iff_of_left_lt_countP.{u_1} {α : Type u_1} {n : ℕ} {p : α → Bool}
  {m : ℕ} {xs : List α} (hn : n < List.countP p xs) :
  List.findIdxNth p xs n = List.findIdxNth p xs m ↔ n = m

theorem List.getElem_findIdxs_eq_findIdxNth_add.{u_1} {α : Type u_1} {n : ℕ} {p : α → Bool} {s : ℕ}
  {xs : List α} {h : n < (List.findIdxs p xs s).length} :
