theorem List.findIdxNth_countPBefore_of_lt_length_of_pos.{u_1} {α : Type u_1} {i : ℕ} {p : α → Bool}
  {xs : List α} {h : i < xs.length} (hip : p xs[i] = true) :
  List.findIdxNth p xs (List.countPBefore p xs i) = i

theorem List.findIdxNth_cons_of_pos.{u_1} {α : Type u_1} {p : α → Bool} {xs : List α} {n : ℕ} {a : α}
  (h : p a = true) :
  List.findIdxNth p (a :: xs) n = if n = 0 then 0 else List.findIdxNth p xs (n - 1) + 1

theorem List.getElem_filter_eq_getElem_getElem_findIdxs_sub.{u_1} {i : ℕ} {α : Type u_1} {xs : List α}
  {p : α → Bool} (s : ℕ) (h : i < (List.filter p xs).length) :
  (List.filter p xs)[i] = xs[(List.findIdxs p xs s)[i] - s]

theorem List.coe_sigmaCountToIdx.{u_1} {α : Type u_1} [BEq α] {xs : List α}
  {xc : (x : α) × Fin (List.count x xs)} :
  ↑(xs.sigmaCountToIdx xc) = List.idxOfNth xc.fst xs ↑xc.snd
